def e(v): return html.escape(str(v))
def pill(t): return f'<span class="pill">{t}</span>'
def metric(value, label, detail='', tone=''):
 return f'<div class="metric {tone}"><div class="value">{value}</div><h3>{label}</h3><p>{detail}</p></div>'
def flow(items):
 return '<div class="flow">'+'<span class="arrow">→</span>'.join(f'<div><b>{x}</b><span>{y}</span></div>' for x,y in items)+'</div>'
def table(headers, rows, cls=''):
 return f'<table class="{cls}"><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def bars(title, labels, values, maximum, unit='', accent=1):
 # 숫자는 원자료의 값만 사용한다. 막대는 0부터 시작하는 선형 스케일이다.
 out=f'<div class="chart"><h3>{title}</h3><div class="chart-scale">0<span>{maximum:g}{unit}</span></div>'
 for i,(label,value) in enumerate(zip(labels,values)):
  number = f'{value:.3f}' if maximum<=1 else (f'{value:,.0f}' if all(float(v).is_integer() for v in values) else f'{value:,.2f}')
  out+=f'<div class="bar-row"><div class="bar-label">{label}</div><div class="track"><div class="bar {"accent" if i==accent else ""}" style="width:{value/maximum*100:.5f}%"></div></div><strong>{number}{unit}</strong></div>'
 return out+'</div>'
def note(t): return f'<div class="takeaway">{t}</div>'
def caveat(t): return f'<p class="caveat">{t}</p>'

