add('프로젝트 소개', '프로젝트 개요', 30, '<div class="scene b-scene"><div class="project-overview"><h2>열영상에서 사람을 검출하고,<br>선택한 표적을 2축 짐벌로 추적하는 시스템</h2><p>LWIR: 장파적외선 열영상 · DEEPX NPU: 보드에서 검출 모델을 실행하는 가속기</p><div class="b-chain"><div><small>01 · 입력</small><h3>열화상 카메라</h3><p>열영상 수신</p></div><b>→</b><div><small>02 · 인식</small><h3>사람 검출 · ID 유지</h3><p>보드에서 영상 처리</p></div><b>→</b><div><small>03 · 선택</small><h3>추적할 표적 지정</h3><p>PC에서 대상 선택</p></div><b>→</b><div><small>04 · 동작</small><h3>2축 짐벌 추종</h3><p>카메라 방향 제어</p></div></div></div></div>', '저희 프로젝트는 열영상에서 사람을 검출하고, 사용자가 고른 사람을 카메라가 따라가도록 하는 시스템입니다. LWIR은 장파적외선 열영상이고, DEEPX NPU는 보드에서 검출 모델을 실행하는 가속기입니다. 카메라 영상에서 사람과 ID를 구한 뒤, PC에서 추적할 대상을 고르면 그 위치를 좌우·상하 짐벌 제어로 연결합니다. 이 네 단계가 하나로 이어지는 것이 프로젝트의 목표입니다.', ['S2', 'S5', 'S8'], '', [])

add('시스템 요구사항', '목표 · 요구사항', 45, '<div class="scene b-scene"><div class="b-requirements"><div><b>01</b><h3>시간</h3><p>30Hz 목표 · 입력 주기 약 33.3ms</p></div><div><b>02</b><h3>검출</h3><p>거리 범위 안에서 사람 찾기</p></div><div><b>03</b><h3>추적</h3><p>가림 뒤에도 선택 ID 이어가기</p></div><div><b>04</b><h3>운용</h3><p>2축 추종 · PC 상태 확인 · 정지</p></div></div><div class="scene-caption">30Hz는 목표. 거리 범위·ID 유지 기준은 최종 확정 전.</div></div>', '저희가 잡은 요구사항은 네 가지입니다. 시간 측면에서는 30헤르츠 입력을 따라가는 것을 목표로 했습니다. 입력 주기로는 약 33.3밀리초입니다. 검출은 정한 거리 범위에서 사람이 잡혀야 하고, 추적은 가림 뒤에도 선택한 ID가 이어져야 합니다. 마지막으로 짐벌 두 축이 그 표적을 따라가고 PC에서 상태를 확인하고 정지할 수 있어야 합니다. 거리와 ID 유지의 수치 기준은 최종 시험 전에 확정해야 하는 항목으로 남겨뒀습니다.', ['S1', 'S2'], '', ['거리 범위·ID 유지 기준'])

add('시스템 구성', '전체 시스템', 35, '<div class="scene b-scene"><div class="system-scene"><div class="system-row"><div class="device">열화상 카메라<small>영상 입력</small></div><span>→</span><div class="board"><small>Orange Pi · DEEPX NPU</small><strong>사람 검출 → 선택 추적기</strong><small>C++ Runtime · 추적기 3종</small></div><span>→</span><div class="device">2축 짐벌<small>짐벌 제어</small></div></div><div class="feedback">← 카메라 방향이 바뀌면 다음 영상에 반영 ←</div><div class="operator"><b>PC GUI</b><span>영상·상태 확인 ↔ 표적 선택·수동 조작·정지</span></div></div><div class="scene-caption">영상·판단·제어의 기능 구성도</div></div>', '윗줄을 따라가면 전체 동작이 보입니다. 카메라에서 보드로 영상이 들어오고, 보드가 사람과 ID를 구합니다. 선택한 표적의 위치가 짐벌로 전달되면 카메라 방향이 바뀝니다. 바뀐 영상이 다시 입력됩니다. PC GUI는 이 반복 동작을 보면서 표적 선택과 수동 조작을 전달합니다. 최신 추적 자료에 따라 ByteTrack, OC-SORT, BoT-SORT 세 가지를 GUI에서 선택하는 구조를 반영했습니다.', ['S2', 'S3', 'S4', 'S14'], '', [])

add('소프트웨어 구성', '구현 경계', 35, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>C++ Runtime</h3><p>영상 수신 · NPU 검출</p></div><b>→</b><div><small>02</small><h3>공통 Tracker</h3><p>ByteTrack · OC-SORT · BoT-SORT</p></div><b>→</b><div><small>03</small><h3>제어 · 통신</h3><p>표적 위치 · PC 명령·상태</p></div></div></div>', '팀원의 최신 자료에서는 세 추적기를 C++ 공통 인터페이스로 구현했습니다. Runtime은 검출 결과를 선택한 추적기에 넘기고, ID와 위치를 PC 표시와 제어에 연결합니다. 세 알고리즘은 같은 검출을 입력받으므로 추적기별 연결 품질을 비교하고 운용 중 선택할 수 있습니다.', ['S3', 'S4', 'S14'], '', [])

add('열화상 검출 과제', '01 · 사람 찾기', 30, '<div class="scene b-scene"><div class="stage"><figure class="photo"><img src="assets/label-outdoor.png" alt="야외 열화상 라벨링 작업 화면"><figcaption>팀 제공 야외 라벨링 작업 화면</figcaption></figure><div class="statement"><h2>작게 보임<br>일부 가려짐</h2><p>검출 누락 →<br>추적 입력도 사라짐</p></div></div></div>', '첫 번째 문제는 검출입니다. 멀리 있는 사람은 작게 보이고, 사람이나 구조물에 일부가 가려지기도 합니다. 이 단계에서 사람이 빠지면 추적기가 연결할 입력도 없어집니다. 그래서 먼저 열화상에서 사람 상자를 일관되게 잡도록 데이터를 준비했습니다.', ['S5', 'S11'], '', [])

add('학습 데이터 구축', '01 · 데이터 준비', 35, '<div class="scene b-scene"><div class="two b-label-images"><figure><img src="assets/label-indoor.png" alt="실내 라벨링 작업 화면"><figcaption>실내 라벨링 작업</figcaption></figure><figure><img src="assets/label-outdoor.png" alt="실외 라벨링 작업 화면"><figcaption>실외 라벨링 작업</figcaption></figure></div><div class="ribbon">사람 위치 확인 → 상자 기준 통일 → 검증셋 고정</div></div>', '제공된 실내와 실외 라벨링 작업 화면입니다. 열화상은 일반 영상과 보이는 특징이 다르기 때문에, 사람 위치와 상자의 기준을 맞춰야 했습니다. 학습 데이터만 늘리는 것으로 끝내지 않고 검증셋을 고정해서 비교 기준을 유지했습니다. 화면은 데이터 작업의 예시이며, 이 두 화면만으로 데이터 검수가 모두 끝났다고 판단하지는 않습니다.', ['S5', 'S11'], '', [])

add('모델 학습 결과', '01 · 학습 확인', 35, '<div class="scene b-scene"><div class="b-curve"><img src="assets/y26m-validation.svg" alt="실제 YOLO26m 30 epoch 검증 AP 곡선"></div><div class="b-keywords"><span>실제 실행 로그</span><span>같은 검증셋</span><span>장치 INT8 평가는 별도</span></div><div class="scene-caption">FLIR 검증 1,144장 · 사람 GT 4,470개 · 원본 30-epoch CSV</div></div>', '이 그림은 YOLO26m의 실제 30에포크 학습에서 나온 검증 곡선입니다. 사람 AP는 첫 에포크 43.75에서 마지막 50.62퍼센트로 변했습니다. 같은 실행에서의 검증 변화이며, 마지막 에포크가 최적이라는 증거는 아닙니다. 또 이 점수를 다음의 보드 INT8 점수와 직접 비교하지 않습니다. 다음 단계는 학습된 모델을 실제 장치에서 평가하는 것입니다.', ['S11'], '', [])

add('검출 성능 비교', '01 · 검출 성능 비교', 35, '<div class="scene b-scene"><div class="chart-result"><div><div class="evidence-chart"><h3>사람 AP50–95 ↑</h3><svg viewBox="0 0 1100 460" role="img" aria-label="사람 AP50–95 ↑: YOLO26s 42.32%, YOLO26m 45.79%"><title>사람 AP50–95 ↑</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">25</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">50</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">75</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">100</text><text x="10" y="174" fill="#35475b" font-size="31">YOLO26s</text><rect x="250" y="130" width="275.0800" height="65" rx="5" fill="#abbccc"/><text x="541.0800" y="174" fill="#50667b" font-size="35" font-weight="600">42.32</text><text x="10" y="329" fill="#35475b" font-size="31">YOLO26m</text><rect x="250" y="285" width="297.6350" height="65" rx="5" fill="#087fbd"/><text x="563.6350" y="329" fill="#087fbd" font-size="35" font-weight="600">45.79</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">%</text></svg></div></div><div class="change-callout "><span>변화량</span><strong>+3.47<small>%p</small></strong><p>이 비교에서 m의<br>검출 성능이 높음</p></div></div><div class="scene-caption">11-06 DX-M1 INT8 · FLIR 8편 3,749프레임 · 모델별 1회</div></div>', '기존 장치 비교에서 사람 AP는 s 모델 42.32퍼센트, m 모델 45.79퍼센트였습니다. 이 조건에서는 m이 3.47퍼센트포인트 높았습니다. 다만 두 모델은 학습 이력도 달라 크기만의 효과라고 해석하지 않습니다. 이 비교는 선택 근거의 한 사례이고, 최종 운용 후보의 새 결과와도 구분해야 합니다.', ['S6'], '', [])

add('추론 시간 비교', '01 · 장치 시간 비교', 35, '<div class="scene b-scene"><div class="chart-result"><div><div class="evidence-chart"><h3>NPU 호출 중앙값 ↓</h3><svg viewBox="0 0 1100 460" role="img" aria-label="NPU 호출 중앙값 ↓: YOLO26s 19.02ms, YOLO26m 27.12ms"><title>NPU 호출 중앙값 ↓</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">10</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">20</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">30</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">40</text><text x="10" y="174" fill="#35475b" font-size="31">YOLO26s</text><rect x="250" y="130" width="309.0750" height="65" rx="5" fill="#abbccc"/><text x="575.0750" y="174" fill="#50667b" font-size="35" font-weight="600">19.02</text><text x="10" y="329" fill="#35475b" font-size="31">YOLO26m</text><rect x="250" y="285" width="440.7000" height="65" rx="5" fill="#a66a28"/><text x="706.7000" y="329" fill="#a66a28" font-size="35" font-weight="600">27.12</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">ms</text></svg></div></div><div class="change-callout tradeoff"><span>변화량</span><strong>+8.10<small>ms</small></strong><p>m은 검출 성능이 높은 대신<br>호출시간이 더 필요</p></div></div><div class="scene-caption">앞 장과 같은 DX-M1 비교 · 호출 p50 · 카메라→화면 종단 지연과 구분</div></div>', '같은 비교에서 NPU 호출 중앙값은 s가 19.02밀리초, m이 27.12밀리초였습니다. m 모델은 검출 성능이 높았지만 호출에는 더 긴 시간이 필요했습니다. 이 시간은 전체 화면 지연이나 짐벌 반응 시간이 아닙니다. 모델 선택에서는 정확도와 장치의 처리 여유를 함께 보고, 마지막에는 같은 현장 조건으로 비교해야 합니다.', ['S6'], '', [])

add('모델 배포 과정', '01 · 배포', 30, '<div class="scene b-scene"><div class="b-diagram"><span class="chapter">학습에서 장치 실행까지</span><div class="b-chain"><div><small>01</small><h3>학습 가중치</h3><p>검증 결과 확인</p></div><b>→</b><div><small>02</small><h3>변환 · INT8 배포</h3><p>장치 실행용 모델</p></div><b>→</b><div><small>03</small><h3>보드 실행</h3><p>시간 · 검출 결과 재확인</p></div></div></div></div>', '학습이 끝나도 그 가중치를 그대로 보드 성능이라고 말할 수는 없습니다. 장치 실행용으로 변환하고 INT8 모델을 배포한 뒤, 검출 결과와 시간을 다시 확인합니다. 영상 밝기 변환과 신경망 INT8 양자화는 서로 다른 작업입니다. 학습, 변환, 장치 실행의 결과를 연결해서 확인하는 단계입니다.', ['S5', 'S6'], '', [])

add('표적 가림과 ID 유지', '02 · ID 이어가기', 35, '<div class="scene b-scene"><div class="identity-story"><div><span class="chapter">보인다</span><div class="person-box">ID 12</div></div><span class="link-arrow">→</span><div><span class="chapter">가려진다</span><div class="occluder">관측 없음</div></div><span class="link-arrow">→</span><div><span class="chapter">다시 나타난다</span><div class="person-box">ID 12 <b>?</b></div></div></div><div class="ribbon">예측 위치만 따라가지 않고, 실제 관측으로 다시 연결</div><div class="scene-caption">가림·재등장 문제를 설명하는 개념도 · OC-SORT의 관측 방향·마지막 관측·재등장 갱신 활용</div></div>', '검출 다음은 같은 사람으로 연결하는 문제입니다. 사용자가 12번을 선택했다고 하겠습니다. 잠깐 가려졌다가 나왔을 때 다른 번호가 붙으면 선택 표적과의 연결도 끊깁니다. 사람을 다시 찾는 것과 같은 사람으로 알아보는 것은 다릅니다. 그림은 그 차이를 설명하는 개념도입니다.', ['S8', 'S9'], '', [])

add('추적 알고리즘 구성', '02 · 추적 방법', 35, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>ByteTrack</h3><p>검출 점수별 2단계 매칭</p></div><b>→</b><div><small>02</small><h3>OC-SORT</h3><p>실제 관측으로 가림 뒤 연결</p></div><b>→</b><div><small>03</small><h3>BoT-SORT</h3><p>박스 상태·점수 반영 매칭</p></div></div><div class="ribbon">공통 C++ 인터페이스 · GUI에서 3종 선택</div><div class="scene-caption">정하건 v3 자료 기준 · BoT-SORT 비교에서 ReID·CMC 미사용</div></div>', '최신 추적 자료에는 ByteTrack, OC-SORT, BoT-SORT 세 가지가 있습니다. ByteTrack은 비교 기준이고, OC-SORT는 실제 관측을 활용해 재연결합니다. BoT-SORT는 박스의 폭과 높이를 따로 추정하고 검출 점수를 매칭 비용에 반영합니다. 이번 비교에서는 외형 비교와 카메라 움직임 보정을 사용하지 않았습니다. 구조와 튜닝 상세는 정하건 팀원의 파트에서 설명합니다.', ['S8', 'S9', 'S14'], '', [])

add('추적 연속성 비교', '02 · 추적 개선 결과', 40, '<div class="scene b-scene"><div class="chart-result"><div><div class="evidence-chart"><h3>ID 변경 횟수 ↓</h3><svg viewBox="0 0 1100 460" role="img" aria-label="ID 변경 횟수 ↓"><title>ID 변경 횟수 ↓</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">150</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">300</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">450</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">600</text><text x="10" y="174" fill="#35475b" font-size="31">OC-SORT</text><rect x="250" y="130" width="575.25" height="65" rx="5" fill="#abbccc"/><text x="841.25" y="174" font-size="35" fill="#234f77" font-weight="600">531</text><text x="10" y="329" fill="#35475b" font-size="31">BoT-SORT</text><rect x="250" y="285" width="613.1666666666666" height="65" rx="5" fill="#087fbd"/><text x="879.1666666666666" y="329" font-size="35" fill="#234f77" font-weight="600">566</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">회</text></svg></div></div><div class="change-callout"><span>OC-SORT의 강점</span><strong>35<small>회 적음</small></strong><p>재현율도 87.7%로<br>BoT-SORT의 85.3%보다 높음</p></div></div><div class="scene-caption">동일 YOLO26s 검출 · LWIR 18편 · PC bench_mot17 · TrackEval 합산</div></div>', '같은 PC 비교에서 ID 변경은 OC-SORT 531회, BoT-SORT 566회로 OC-SORT가 적었습니다. 재현율도 OC-SORT가 87.7퍼센트로 더 높았습니다. 새 알고리즘을 추가했다고 모든 지표가 좋아지는 것은 아닙니다. 표적 연결과 놓침을 중시하는 장면에서 OC-SORT가 가진 강점을 함께 봤습니다.', ['S8', 'S9', 'S14'], '', [])

add('추적 품질 및 선택 기준', '02 · 추적 결과 해석', 30, '<div class="scene b-scene"><div class="paired-evidence"><div class="evidence-chart"><h3>종합 지표 HOTA ↑</h3><svg viewBox="0 0 1100 460" role="img" aria-label="종합 지표 HOTA ↑"><title>종합 지표 HOTA ↑</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">25</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">50</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">75</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">100</text><text x="10" y="174" fill="#35475b" font-size="31">OC-SORT</text><rect x="250" y="130" width="384.15" height="65" rx="5" fill="#abbccc"/><text x="650.15" y="174" font-size="35" fill="#234f77" font-weight="600">59.1</text><text x="10" y="329" fill="#35475b" font-size="31">BoT-SORT</text><rect x="250" y="285" width="394.55" height="65" rx="5" fill="#087fbd"/><text x="660.55" y="329" font-size="35" fill="#234f77" font-weight="600">60.7</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">점</text></svg></div><div class="evidence-chart"><h3>신원 연결 IDF1 ↑</h3><svg viewBox="0 0 1100 460" role="img" aria-label="신원 연결 IDF1 ↑"><title>신원 연결 IDF1 ↑</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">25</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">50</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">75</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">100</text><text x="10" y="174" fill="#35475b" font-size="31">OC-SORT</text><rect x="250" y="130" width="433.55" height="65" rx="5" fill="#abbccc"/><text x="699.55" y="174" font-size="35" fill="#234f77" font-weight="600">66.7</text><text x="10" y="329" fill="#35475b" font-size="31">BoT-SORT</text><rect x="250" y="285" width="438.75000000000006" height="65" rx="5" fill="#087fbd"/><text x="704.75" y="329" font-size="35" fill="#234f77" font-weight="600">67.5</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">%</text></svg></div></div><div class="paired-summary"><span>기본 추천 <b>BoT-SORT</b></span><span>가림이 잦은 장면 <b>OC-SORT</b></span></div><div class="scene-caption">같은 PC 평가 · 종합 지표와 ID 유지·누락의 절충에 따른 추천 · 실제 데모 선택값은 별도 기록</div></div>', 'BoT-SORT는 HOTA 60.7과 IDF1 67.5퍼센트로 이번 비교의 종합 지표가 가장 높았습니다. 정밀도와 MOTA도 높지만 ID 변경과 재현율은 앞 장의 OC-SORT가 유리합니다. 팀원 자료의 결론은 기본 추천은 BoT-SORT, 가림이 잦은 장면은 OC-SORT입니다. 세 종류를 남겨 GUI에서 바꾸도록 한 이유입니다. 이 추천과 실제 시연에서 사용한 설정은 구분해 기록합니다.', ['S9', 'S14'], '', [])

add('처리 지연 요인', '03 · 처리 흐름', 35, '<div class="scene b-scene"><div class="b-diagram"><span class="chapter">대기가 쌓이는 경로</span><div class="b-chain"><div><small>01</small><h3>입력 대기</h3><p>다음 프레임 준비</p></div><b>→</b><div><small>02</small><h3>추론 대기</h3><p>요청 제출·완료</p></div><b>→</b><div><small>03</small><h3>출력 대기</h3><p>추적·영상 전달</p></div></div></div><div class="ribbon">모델 호출시간 외에, 단계 사이 대기도 확인</div></div>', '추적 결과가 맞아도 한참 늦게 도착하면 짐벌은 이미 지나간 위치를 따라가게 됩니다. 지연은 모델 호출에서만 생기지 않습니다. 입력 준비와 제출 사이, 결과 처리와 출력 사이에서도 기다릴 수 있습니다. 그래서 개별 함수의 시간과 함께 처리 흐름의 대기를 확인했습니다.', ['S4', 'S12'], '', [])

add('비동기 요청 처리', '03 · 요청 중첩', 35, '<div class="scene b-scene"><div class="queue-scene"><div><span class="chapter">직렬 대기</span><div class="queue"><i>입력</i><i>추론</i><i>대기</i><i>출력</i></div></div><div><span class="chapter">요청을 겹쳐 처리</span><div class="queue fast"><i>입력</i><i>추론 ↔ 다음 입력</i><i>출력</i></div></div></div><div class="scene-caption">개념도 · 별도 C++ Runtime의 미완료 요청 상한 1→4 비교</div></div>', '김재남 팀원의 별도 C++ Runtime 시험에서는 요청을 겹쳐 처리하는 조건을 비교했습니다. 한 요청의 완료를 기다리는 동안 다음 입력을 준비하고 제출하는 방식입니다. 미완료 요청 상한을 1에서 4로 바꿨습니다. 여기서 4는 NPU 코어 개수가 아니라 동시에 미완료 상태로 둘 수 있는 요청의 상한입니다.', ['S12'], '', [])

add('처리 지연 개선 결과', '03 · 처리 결과', 35, '<div class="scene b-scene"><div class="chart-result"><div><div class="evidence-chart"><h3>입력 준비→추적 완료 p95 ↓</h3><svg viewBox="0 0 1100 460" role="img" aria-label="입력 준비→추적 완료 p95 ↓: 요청 상한 1 74.42ms, 요청 상한 4 22.75ms"><title>입력 준비→추적 완료 p95 ↓</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">20</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">40</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">60</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">80</text><text x="10" y="174" fill="#35475b" font-size="31">요청 상한 1</text><rect x="250" y="130" width="604.6625" height="65" rx="5" fill="#abbccc"/><text x="870.6625" y="174" fill="#50667b" font-size="35" font-weight="600">74.42</text><text x="10" y="329" fill="#35475b" font-size="31">요청 상한 4</text><rect x="250" y="285" width="184.8438" height="65" rx="5" fill="#087fbd"/><text x="450.8438" y="329" fill="#087fbd" font-size="35" font-weight="600">22.75</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">ms</text></svg></div></div><div class="change-callout "><span>변화량</span><strong>−69.4<small>%</small></strong><p>재생 부하 조건에서<br>결과 지연 감소</p></div></div><div class="scene-caption">실제 NPU · 객체 0개 재생 입력 · 조건별 15초×3회 · 웹·짐벌 제외</div></div>', '60fps 메모리 재생 입력과 실제 NPU를 사용한 별도 시험에서 결과 지연 p95가 74.42에서 22.75밀리초로 줄었습니다. 입력은 객체가 없는 프레임의 반복이며 GUI와 짐벌은 포함하지 않습니다. 따라서 전체 시스템이 실카메라 60fps를 달성했다거나 화면까지 이 시간에 도착한다는 뜻은 아닙니다.', ['S12'], '', [])

add('표적 위치 오차', '03 · 2축 제어', 35, '<div class="scene b-scene"><div class="stage"><div class="aim-scene"><div class="crosshair"></div><div class="target-box"><span>선택 표적</span><b>●</b></div><div class="error-arrow">← 위치 오차 →</div><span class="aim-label">화면 목표점</span></div><div class="statement"><span class="chapter">Pan · Tilt</span><h2>표적 조준점<br>화면 목표점<br>두 축의 오차</h2><p>표적 위치를<br>제어 입력으로</p></div></div><div class="scene-caption">제어 개념도 · 실제 카메라·짐벌 + 가상 표적 시험 수행. 실제 사람 현장 추종은 최종 확인 필요.</div></div>', '사용자가 고른 사람 상자에서 조준점을 구합니다. 그 점이 원하는 화면 위치에서 얼마나 떨어졌는지 계산합니다. 이 오차가 좌우와 상하 움직임의 입력이 됩니다. 화면의 표적 위치와 목표점이 제어로 이어지는 경계입니다.', ['S2', 'S3', 'S11'], '', ['실제 브리지·PD·조준점·속도 설정'])

add('PD 제어', '04 · PD 제어', 35, '<div class="scene b-scene"><div class="b-pd"><div><b>P</b><h2>얼마나 벗어났나</h2><p>현재 위치 오차</p></div><div><b>D</b><h2>얼마나 변하고 있나</h2><p>오차의 변화</p></div></div><div class="ribbon">PD 계산 → 불감대·속도 제한 → Pan·Tilt 명령</div><div class="scene-caption">제어 원리 설명 · 공통 SPD 명령을 실제 각속도나 축별 독립 속도로 해석하지 않음</div></div>', '제어는 현재 위치 오차와 오차의 변화를 함께 봅니다. P는 얼마나 벗어났는지, D는 그 오차가 어떻게 변하는지에 반응합니다. 공개 실행 스크립트는 적분항이 0인 PD 동작입니다. 계산한 값에 불감대와 속도 제한을 적용한 뒤 두 축의 방향과 공통 속도 명령으로 전달합니다. 실제 운용값은 장치 설정과 맞춰야 합니다.', ['S3'], '', [])

add('수동 전환 및 정지', '04 · 수동 전환·정지', 30, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>AUTO</h3><p>선택 ID 위치로 추종</p></div><b>→</b><div><small>02</small><h3>수동 개입</h3><p>방향 입력으로 조작</p></div><b>→</b><div><small>03</small><h3>정지 처리</h3><p>입력 상실·오래된 관측 확인</p></div></div><div class="ribbon">표적이 보이는가 · 입력이 최신인가 · 정지할 수 있는가</div></div>', '추종을 시작하는 것만큼 중단하고 수동으로 바꾸는 것도 중요합니다. 자동 상태에서는 선택한 ID의 위치를 사용하고, 수동 입력이 들어오면 운용자가 방향을 조작할 수 있어야 합니다. 입력 상실이나 오래된 관측을 처리하는 경계도 확인합니다. 최종 시연에서는 이 전환과 정지를 실제 장치 동작으로 보여줘야 합니다.', ['S2', 'S3'], '', [])

add('짐벌 제어 시험', '04 · 제어 시험', 35, '<div class="scene b-scene"><div class="paired-evidence"><div class="evidence-chart"><h3>상하 정지 뒤 반전 ↓</h3><svg viewBox="0 0 1100 460" role="img" aria-label="상하 정지 뒤 반전 ↓: 변경 전 4회, 변경 후 1회"><title>상하 정지 뒤 반전 ↓</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">1</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">2</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">3</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">4</text><text x="10" y="174" fill="#35475b" font-size="31">변경 전</text><rect x="250" y="130" width="650.0000" height="65" rx="5" fill="#abbccc"/><text x="916.0000" y="174" fill="#50667b" font-size="35" font-weight="600">4</text><text x="10" y="329" fill="#35475b" font-size="31">변경 후</text><rect x="250" y="285" width="162.5000" height="65" rx="5" fill="#087fbd"/><text x="428.5000" y="329" fill="#087fbd" font-size="35" font-weight="600">1</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">회</text></svg></div><div class="evidence-chart"><h3>별도 가로 뒤처짐 ↓</h3><svg viewBox="0 0 1100 460" role="img" aria-label="별도 가로 뒤처짐 ↓: 변경 전 14.3px, 변경 후 18.6px"><title>별도 가로 뒤처짐 ↓</title><line x1="250.0" x2="250.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="250.0" y="415" text-anchor="middle" fill="#718096" font-size="25">0</text><line x1="412.5" x2="412.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="412.5" y="415" text-anchor="middle" fill="#718096" font-size="25">5</text><line x1="575.0" x2="575.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="575.0" y="415" text-anchor="middle" fill="#718096" font-size="25">10</text><line x1="737.5" x2="737.5" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="737.5" y="415" text-anchor="middle" fill="#718096" font-size="25">15</text><line x1="900.0" x2="900.0" y1="75" y2="370" stroke="#e1e8ef" stroke-width="2"/><text x="900.0" y="415" text-anchor="middle" fill="#718096" font-size="25">20</text><text x="10" y="174" fill="#35475b" font-size="31">변경 전</text><rect x="250" y="130" width="464.7500" height="65" rx="5" fill="#abbccc"/><text x="730.7500" y="174" fill="#50667b" font-size="35" font-weight="600">14.3</text><text x="10" y="329" fill="#35475b" font-size="31">변경 후</text><rect x="250" y="285" width="604.5000" height="65" rx="5" fill="#a66a28"/><text x="870.5000" y="329" fill="#a66a28" font-size="35" font-weight="600">18.6</text><text x="900" y="452" text-anchor="end" fill="#718096" font-size="23">px</text></svg></div></div><div class="paired-summary"><span>반전 <b>3회 감소</b></span><span>가로 뒤처짐 <b class="worse">4.3px 증가</b></span></div><div class="scene-caption">11-10 실제 카메라·짐벌 + 가상 표적 · 조건별 1회 · 속도 상한 10 / aim 0.3</div></div>', '실제 카메라와 짐벌에 가상 표적을 주는 과거 시험에서는 상하 정지 뒤 반전이 네 번에서 한 번으로 줄었습니다. 반면 별도 가로 시험의 뒤처짐은 14.3에서 18.6픽셀로 늘었습니다. 조건별 한 번씩의 시험이므로 전체 추종이 좋아졌다고 일반화하지 않았습니다. 실제 사람을 따라가는 현장 시험은 별도로 필요합니다.', ['S5', 'S6', 'S11'], '', [])

add('GUI 구성', 'PC 운용 화면', 30, '<div class="scene b-scene"><div class="demo-gui-placeholder"><h2>실제 데모 GUI 화면</h2><p>운용 앱 캡처 삽입 예정</p></div><div class="b-keywords"><span>영상 · BBox</span><span>추적기 3종 · 선택 ID</span><span>연결 · 처리 상태</span></div></div>', 'GUI에서는 영상과 사람 상자, 선택 ID와 모드, 연결 상태를 확인합니다. 최신 팀원 자료에 따라 세 추적기를 선택하고 변경 완료를 확인하는 기능도 설명합니다. 화면은 실제 데모 앱 캡처가 들어올 자리입니다. 팀원 자료를 연동 기능의 근거로 사용하며, 이번 편집에서 장치 시험을 새로 수행한 것은 아닙니다.', ['S2', 'S3', 'S4', 'S14'], '', ['실제 데모 앱과 GUI 캡처 확인'])

add('GUI 조작 순서', '05 · GUI 조작 흐름', 30, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>추적기 선택</h3><p>ByteTrack · OC-SORT · BoT-SORT</p></div><b>→</b><div><small>02</small><h3>변경 확인</h3><p>접수 → 완료 응답</p></div><b>→</b><div><small>03</small><h3>표적 선택</h3><p>선택 ID · 모드 확인</p></div><b>→</b><div><small>04</small><h3>수동 · 정지</h3><p>운용자 개입</p></div></div></div>', '먼저 사용할 추적기를 선택하고 변경 완료를 확인합니다. 그 다음 추적할 ID와 모드를 고르고 필요할 때 수동으로 개입하거나 정지합니다. 추적기 교체 요청과 표적 ID 선택은 서로 다른 조작입니다. 교체 후 기존 선택 ID의 유지·해제 정책은 실제 데모 설정에서 확인할 항목입니다.', ['S2', 'S3', 'S14'], '', [])

add('추적기 변경 및 응답', '05 · GUI 연결', 30, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>PC GUI</h3><p>추적기 번호 선택</p></div><b>→</b><div><small>02</small><h3>TCP 요청</h3><p>Runtime에 변경 요청</p></div><b>→</b><div><small>03</small><h3>Runtime 교체</h3><p>카탈로그 설정 · 프레임 경계</p></div><b>→</b><div><small>04</small><h3>결과 확인</h3><p>Accepted → Completed</p></div></div><div class="ribbon">생성 실패 시 기존 추적기 유지</div><div class="scene-caption">정하건 v3 · 추적기 조회 0x02/0x82 · 변경 0x04/0x84 · PC–Runtime TCP 경로</div></div>', '팀원의 최신 자료에 따르면 GUI에서 추적기 번호를 선택하면 TCP로 변경 요청을 보냅니다. Runtime은 카탈로그에서 설정을 찾고 새 추적기를 생성해 다음 프레임 경계에서 교체합니다. GUI는 접수 응답과 완료 응답을 구분해 결과를 확인하며, 생성 실패 시 Runtime은 기존 추적기를 유지합니다. 알고리즘 내부 구현은 팀원 파트에서, 요청과 상태 확인은 GUI·통신 파트에서 설명합니다.', ['S3', 'S4', 'S10', 'S14'], '', ['실제 데모 캡처·선택 추적기·교체 후 표적 ID 정책'])

add('시연 구성', '통합 데모 안내', 25, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>검출 · 선택</h3><p>사람과 ID 확인</p></div><b>→</b><div><small>02</small><h3>이동 · 추종</h3><p>Pan·Tilt 반응</p></div><b>→</b><div><small>03</small><h3>가림 · 재포착</h3><p>ID와 상실 상태</p></div><b>→</b><div><small>04</small><h3>수동 · 정지</h3><p>운용자 개입</p></div></div><div class="scene-caption">실제 영상 수령 전의 시연 구성안</div></div>', '시연은 이 네 장면 순서로 보겠습니다. 먼저 검출과 표적 선택, 다음은 움직임에 따른 짐벌 반응, 가림과 재등장, 마지막은 수동 전환과 정지입니다. 각 장면에서 선택한 ID와 장치의 실제 동작이 함께 보이도록 구성해야 합니다.', ['S2'], '', [])

add('통합 시연', '통합 데모 · 3분', 180, '<div class="scene b-scene"><div class="demo-stage"><div class="demo-placeholder"><span class="chapter">실제 운용 영상 삽입 자리</span><h2>검출 → 선택 → 추종 → 정지</h2><p>assets/rooftop-demo.mp4</p><video id="demo-video" controls preload="none" aria-label="실제 통합 데모"><source src="assets/rooftop-demo.mp4" type="video/mp4"></video></div><div class="demo-sequence"><span>00:00 · 장치·설정 확인</span><span>00:30 · 선택·추종·재포착</span><span>02:15 · 수동 전환·정지</span></div></div><div class="scene-caption">현재 실제 영상 파일 미수령 · 최종 설정과 일치하는 녹화 또는 실시간 시연으로 교체 필요</div></div>', '[데모 영상 3분 슬롯. 실제 영상은 아직 제공되지 않아 포함하지 않았다.]\n0:00–0:30: 실제 장치, 선택 모델과 추적기, 촬영 조건을 짧게 소개한다. 후보 비교 결과가 확정되면 선택 이유 한 문장을 덧붙인다.\n0:30–1:15: 영상에서 사람이 검출되고 ID가 붙는 모습, 사용자가 표적을 선택하는 장면을 보여준다.\n1:15–2:15: 표적 이동에 따른 짐벌 추종, 가림과 재등장 구간을 보여준다. 실제 영상에서 확인된 성공과 끊김을 그대로 설명한다.\n2:15–3:00: 수동 입력과 정지, 화면의 상태 확인을 보여준다. 기록된 수치가 있다면 계측 구간을 붙여 요약한다.\n실제 영상이 없을 때 삽입 안내 화면을 동작 시연으로 설명하지 않는다. 실제 영상 파일이 들어오기 전에는 최종 리허설을 완료로 표시하지 않는다.', ['S1', 'S2', 'S6'], '', ['실제 통합 영상 180초 이내'])

add('검출 거리 검증', '최종 검증 · 검출', 30, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>조건 고정</h3><p>모델 · 해상도 · 장소</p></div><b>→</b><div><small>02</small><h3>거리별 관측</h3><p>사람 크기 · 누락·오검출</p></div><b>→</b><div><small>03</small><h3>범위 판정</h3><p>정한 기준으로 결과 기록</p></div></div><div class="ribbon">검출 거리: 하한·상한 및 통과 기준 확정 필요</div></div>', '현장에서는 먼저 거리별 검출을 확인합니다. 모델과 해상도, 장소를 고정하고 사람이 얼마나 작아지는지와 누락, 오검출을 함께 기록합니다. 몇 미터부터 몇 미터까지를 요구할지와 통과 기준은 아직 확정 전입니다. 기존 AP 점수를 거리 성능으로 대신 적지 않고 같은 현장에서 측정해야 합니다.', ['S2', 'S11'], '', ['검출 거리 기준과 측정값'])

add('ID 유지 검증', '최종 검증 · 추적', 30, '<div class="scene b-scene"><div class="b-chain"><div><small>01</small><h3>표적 이동</h3><p>선택 ID의 연속성</p></div><b>→</b><div><small>02</small><h3>가림 · 재등장</h3><p>상실·재포착 확인</p></div><b>→</b><div><small>03</small><h3>추종 확인</h3><p>같은 ID의 위치→짐벌</p></div></div><div class="ribbon">ID 변경 · 끊김 · 재포착 시간을 함께 기록</div></div>', '추적은 선택한 사람이 이동하고 가려졌다가 다시 나타나는 순서로 확인합니다. ID가 유지되는지뿐 아니라, 놓쳤을 때 상실 상태가 표시되고 다시 잡을 때 어떻게 동작하는지도 봅니다. 유지 시간과 허용 끊김 같은 통과 기준은 최종 확정하고 같은 동선으로 비교해야 합니다.', ['S2', 'S9'], '', ['ID 유지·끊김 기준과 현장 결과'])

add('처리량 및 지연 검증', '최종 검증 · 시간', 30, '<div class="scene b-scene"><div class="b-split"><div><div class="b-number">30Hz</div><h2 class="b-label">목표 입력 주기 ≈ 33.3ms</h2><p class="b-sub">들어오는 속도를 처리하는가</p></div><div><div class="b-number">구간별 지연</div><h2 class="b-label">같은 프레임의 경과시간</h2><p class="b-sub">NPU · 서버 · 화면 · 장치 구분</p></div></div><div class="scene-caption">30Hz 목표 달성 또는 카메라→화면 종단 지연의 확정 결과가 아님</div></div>', '시간은 처리량과 지연을 나눠 보겠습니다. 30헤르츠는 입력 주기가 약 33.3밀리초라는 뜻입니다. 그 속도로 결과가 계속 나오는지와, 같은 프레임이 결과가 되기까지 얼마나 걸리는지는 다릅니다. NPU 호출, 서버 결과, 화면, 장치 반응의 구간을 정하고 계측해야 합니다.', ['S4', 'S12'], '', [])

add('성과 및 향후 과제', '마무리', 35, '<div class="scene b-scene"><div class="closing-scene"><div><span>01</span><h2>찾는다</h2><p>열화상에 맞춘 검출</p></div><div><span>02</span><h2>이어간다</h2><p>같은 사람의 ID 유지</p></div><div><span>03</span><h2>따라간다</h2><p>GUI 선택을 2축 제어로</p></div></div><div class="closing-line">모델 하나의 성능에서, 사용자가 운용하는 흐름까지.</div></div>', '저희 작업은 이 세 동작으로 정리할 수 있습니다. 열화상에 맞춰 사람을 찾고, 추적기로 같은 ID를 이어가고, 사용자 선택을 짐벌 제어와 운용 화면에 연결했습니다. 각 파트의 실험 결과를 확보했고, 마지막은 같은 현장 설정에서 이 흐름을 검증하는 것입니다. 이상 5팀 올빼미였습니다. 감사합니다.', ['S2', 'S11', 'S9', 'S12'], '', [])

