def refs_html(ids):
 return ' · '.join(f'<a href="{e(SOURCES[i][1])}">{i} {e(SOURCES[i][0])}</a>' for i in ids)
def slide_html(s):
 n=s['number']; title=s['title'];
 is_cover = n == 1 and s['section'] == 'LWIR 표적 추적 시스템'
 heading = '' if is_cover else f'<h1>{e(title)}</h1>'
 return f'''<section class="slide{' cover-slide' if is_cover else ''}" id="slide-{n:02d}" data-number="{n}" data-seconds="{s['seconds']}" aria-label="{e(title)}">
 <header>{heading}<img class="logo" src="assets/lig-logo.png" alt="LIG D&A"></header>
 <main>{s['body']}</main>
 <div class="slide-source">{refs_html(s['refs'])}</div>
 <footer><span>{n:02d} / {main_count}</span></footer>
 </section>'''

